UPDATE game_saves
SET save_data = (
  WITH RECURSIVE 
  targets AS (
    SELECT row_number() OVER () as rn, fullkey
    FROM json_tree(game_saves.save_data)
    WHERE type = 'object'
      AND json_extract(value, '$.uid') IS NOT NULL
      AND json_extract(value, '$.steps') IS NULL
      AND json_extract(value, '$.vigor') IS NULL
  ),
  apply(step, cur_data) AS (
    SELECT 0, game_saves.save_data
    UNION ALL
    SELECT step + 1, json_set(apply.cur_data, targets.fullkey || '.vigor', 3, targets.fullkey || '.maxVigor', 3)
    FROM apply
    JOIN targets ON targets.rn = apply.step + 1
  )
  SELECT cur_data FROM apply ORDER BY step DESC LIMIT 1
)
WHERE EXISTS (
  SELECT 1 
  FROM json_tree(game_saves.save_data) 
  WHERE type = 'object' 
    AND json_extract(value, '$.uid') IS NOT NULL 
    AND json_extract(value, '$.steps') IS NULL 
    AND json_extract(value, '$.vigor') IS NULL
);


UPDATE passive_teams
SET team_data = (
  WITH RECURSIVE 
  targets AS (
    SELECT row_number() OVER () as rn, fullkey
    FROM json_tree(passive_teams.team_data)
    WHERE type = 'object'
      AND json_extract(value, '$.uid') IS NOT NULL
      AND json_extract(value, '$.steps') IS NULL
      AND json_extract(value, '$.vigor') IS NULL
  ),
  apply(step, cur_data) AS (
    SELECT 0, passive_teams.team_data
    UNION ALL
    SELECT step + 1, json_set(apply.cur_data, targets.fullkey || '.vigor', 3, targets.fullkey || '.maxVigor', 3)
    FROM apply
    JOIN targets ON targets.rn = apply.step + 1
  )
  SELECT cur_data FROM apply ORDER BY step DESC LIMIT 1
)
WHERE EXISTS (
  SELECT 1 
  FROM json_tree(passive_teams.team_data) 
  WHERE type = 'object' 
    AND json_extract(value, '$.uid') IS NOT NULL 
    AND json_extract(value, '$.steps') IS NULL 
    AND json_extract(value, '$.vigor') IS NULL
);


UPDATE trade_offers
SET offer_pokemon = json_set(offer_pokemon, '$.vigor', 3, '$.maxVigor', 3)
WHERE offer_pokemon IS NOT NULL
  AND json_extract(offer_pokemon, '$.uid') IS NOT NULL
  AND json_extract(offer_pokemon, '$.vigor') IS NULL;

UPDATE trade_offers
SET request_pokemon = json_set(request_pokemon, '$.vigor', 3, '$.maxVigor', 3)
WHERE request_pokemon IS NOT NULL
  AND json_extract(request_pokemon, '$.uid') IS NOT NULL
  AND json_extract(request_pokemon, '$.vigor') IS NULL;

UPDATE claim_queue
SET asset_data = json_set(asset_data, '$.data.vigor', 3, '$.data.maxVigor', 3)
WHERE asset_data IS NOT NULL
  AND json_extract(asset_data, '$.type') = 'pokemon'
  AND json_extract(asset_data, '$.data.vigor') IS NULL;

UPDATE market_listings
SET data = json_set(data, '$.vigor', 3, '$.maxVigor', 3)
WHERE data IS NOT NULL
  AND json_extract(data, '$.uid') IS NOT NULL
  AND json_extract(data, '$.vigor') IS NULL;

UPDATE war_defenders
SET pokemon_data = json_set(pokemon_data, '$.vigor', 3, '$.maxVigor', 3)
WHERE pokemon_data IS NOT NULL
  AND json_extract(pokemon_data, '$.uid') IS NOT NULL
  AND json_extract(pokemon_data, '$.vigor') IS NULL;


