UPDATE trade_offers SET offer_pokemon = replace(offer_pokemon, '"id":"quickattack"', '"id":"swift"') WHERE offer_pokemon LIKE '%"id":"starmie"%' OR offer_pokemon LIKE '%"species":"starmie"%';
UPDATE trade_offers SET request_pokemon = replace(request_pokemon, '"id":"quickattack"', '"id":"swift"') WHERE request_pokemon LIKE '%"id":"starmie"%' OR request_pokemon LIKE '%"species":"starmie"%';
UPDATE trade_offers SET offer_pokemon = replace(offer_pokemon, '"id":"lockon"', '"id":"defensecurl"') WHERE offer_pokemon LIKE '%"id":"graveler"%' OR offer_pokemon LIKE '%"species":"graveler"%' OR offer_pokemon LIKE '%"id":"golem"%' OR offer_pokemon LIKE '%"species":"golem"%';
UPDATE trade_offers SET request_pokemon = replace(request_pokemon, '"id":"lockon"', '"id":"defensecurl"') WHERE request_pokemon LIKE '%"id":"graveler"%' OR request_pokemon LIKE '%"species":"graveler"%' OR request_pokemon LIKE '%"id":"golem"%' OR request_pokemon LIKE '%"species":"golem"%';
UPDATE market_listings SET data = replace(data, '"id":"poisonsting"', '"id":"poisonpowder"') WHERE (data LIKE '%"id":"venonat"%' OR data LIKE '%"species":"venonat"%') AND data LIKE '%"id":"poisonsting"%';
UPDATE war_defenders SET pokemon_data = replace(pokemon_data, '"id":"thrash"', '"id":"bodyslam"') WHERE (pokemon_data LIKE '%"id":"snorlax"%' OR pokemon_data LIKE '%"species":"snorlax"%') AND pokemon_data LIKE '%"id":"thrash"%';
UPDATE war_defenders SET pokemon_data = replace(pokemon_data, '"id":"harden"', '"id":"defensecurl"') WHERE (pokemon_data LIKE '%"id":"chansey"%' OR pokemon_data LIKE '%"species":"chansey"%') AND pokemon_data LIKE '%"id":"harden"%';
UPDATE war_defenders SET pokemon_data = replace(pokemon_data, '"id":"stomp"', '"id":"bodyslam"') WHERE (pokemon_data LIKE '%"id":"poliwhirl"%' OR pokemon_data LIKE '%"species":"poliwhirl"%') AND pokemon_data LIKE '%"id":"stomp"%';
UPDATE war_defenders SET pokemon_data = replace(pokemon_data, '"id":"wingattack"', '"id":"gust"') WHERE (pokemon_data LIKE '%"id":"venomoth"%' OR pokemon_data LIKE '%"species":"venomoth"%') AND pokemon_data LIKE '%"id":"wingattack"%';
UPDATE passive_teams SET team_data = replace(team_data, '"id":"quickattack"', '"id":"swift"') WHERE team_data LIKE '%"id":"starmie"%' OR team_data LIKE '%"species":"starmie"%';
UPDATE passive_teams SET team_data = replace(team_data, '"id":"lockon"', '"id":"defensecurl"') WHERE team_data LIKE '%"id":"golem"%' OR team_data LIKE '%"species":"golem"%';

UPDATE passive_teams SET team_data = (
  SELECT json_group_array(
    json_set(
      value,
      '$.hp', coalesce(json_extract(value, '$.hp'), json_extract(value, '$.maxHp'), 100),
      '$.uid', coalesce(json_extract(value, '$.uid'), 'passive-' || json_extract(value, '$.id')),
      '$.vigor', coalesce(json_extract(value, '$.vigor'), 3),
      '$.maxVigor', coalesce(json_extract(value, '$.maxVigor'), 3)
    )
  )
  FROM json_each(passive_teams.team_data)
)
WHERE team_data IS NOT NULL;


